def find_longest_chain(pairs):
    pairs = sorted(pairs)
    n = len(pairs)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for prev in range(i - 1, -2, -1):
            best = dp[i + 1][prev + 1]
            if prev == -1 or pairs[prev][1] < pairs[i][0]:
                best = max(best, 1 + dp[i + 1][i + 1])
            dp[i][prev + 1] = best
    return dp[0][0]

def find_longest_chain(pairs):
    pairs = sorted(pairs)
    n = len(pairs)
    nxt = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        cur = [0] * (n + 1)
        for prev in range(i - 1, -2, -1):
            best = nxt[prev + 1]
            if prev == -1 or pairs[prev][1] < pairs[i][0]:
                best = max(best, 1 + nxt[i + 1])
            cur[prev + 1] = best
        nxt = cur
    return nxt[0]

def find_longest_chain(pairs):
    pairs = sorted(pairs)
    n = len(pairs)
    row = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        take = 1 + row[i + 1]
        for prev in range(i - 1, -2, -1):
            if prev == -1 or pairs[prev][1] < pairs[i][0]:
                row[prev + 1] = max(row[prev + 1], take)
    return row[0]

def find_longest_chain(pairs):
    count, end = 0, -inf
    for a, b in sorted(pairs, key=lambda p: p[1]):
        if a > end:
            count += 1
            end = b
    return count
